module tb_TopModule;
    reg clk;
    reg j;
    reg k;
    wire Q;

    TopModule dut (
        .clk(clk),
        .j(j),
        .k(k),
        .Q(Q)
    );

    always #5 clk = ~clk;

    initial begin
        clk = 0;
        j = 0;
        k = 0;

        // Initial state after first posedge clk with J=0, K=0 -> Q should be 0 (if uninitialized, wait, in SV regs default to x, but let's set J=1, K=0 first to initialize Q=1)
        #2;
        j = 1; k = 0; // Set Q to 1
        #10;
        if (Q !== 1'b1) begin
            $display("SELFFAIL: Init to 1 failed, Q=%b", Q);
            $finish;
        end

        // Test J=0, K=0 (hold)
        j = 0; k = 0;
        #10;
        if (Q !== 1'b1) begin
            $display("SELFTEST FAIL: 00 hold failed, expected 1, got %b", Q);
            $finish;
        end

        // Test J=0, K=1 (reset)
        j = 0; k = 1;
        #10;
        if (Q !== 1'b0) begin
            $display("SELFTEST FAIL: 01 reset failed, expected 0, got %b", Q);
            $finish;
        end

        // Test J=0, K=0 (hold 0)
        j = 0; k = 0;
        #10;
        if (Q !== 1'b0) begin
            $display("SELFTEST FAIL: 00 hold 0 failed, expected 0, got %b", Q);
            $finish;
        end

        // Test J=1, K=0 (set)
        j = 1; k = 0;
        #10;
        if (Q !== 1'b1) begin
            $display("SELFTEST FAIL: 10 set failed, expected 1, got %b", Q);
            $finish;
        end

        // Test J=1, K=1 (toggle)
        j = 1; k = 1;
        #10;
        if (Q !== 1'b0) begin
            $display("SELFTEST FAIL: 11 toggle 1 failed, expected 0, got %b", Q);
            $finish;
        end

        // Test J=1, K=1 (toggle again)
        #10;
        if (Q !== 1'b1) begin
            $display("SELFTEST FAIL: 11 toggle 2 failed, expected 1, got %b", Q);
            $finish;
        end

        $display("SELFTEST PASS");
        $finish;
    end
endmodule
